/// Apply the ROT13 cipher to the input string.\n///\n/// This function preserves case for alphabetic characters and leaves all other\n/// characters unchanged.\npub fn rot13(input: &str) -> String {\n    input\n        .chars()\n        .map(|c| match c {\n            'a'..='z' => (((c as u8 - b'a' + 13) % 26) + b'a') as char,\n            'A'..='Z' => (((c as u8 - b'A' + 13) % 26) + b'A') as char,\n            _ => c,\n        })\n        .collect()\n}\n
